import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { postChatHandler } from "../handlers/postChatHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldRoundEntityType } from "../types/FactFoldRoundEntityType";
import type { PostChatRequest } from "../types/PostChatRequest";

type Data = Awaited<ReturnType<typeof postChatHandler>>;
type Vars = { roundId: FactFoldRoundEntityType; req: PostChatRequest };

export function usePostChat(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => postChatHandler(vars.roundId, vars.req),
    ...options,
  });
}
